1	/* ============================================================
2	   英雄梯度排行榜 — 公共样式
3	   适配 LOLM 和 曙光英雄，深色主题，响应式
4	   ============================================================ */
5	
6	* { margin: 0; padding: 0; box-sizing: border-box; }
7	
8	body {
9	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
10	                 "Microsoft YaHei", sans-serif;
11	    background: #0d1117;
12	    color: #c9d1d9;
13	    min-height: 100vh;
14	}
15	
16	/* ---- 头部 ---- */
17	.header {
18	    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
19	    padding: 24px 24px 20px;
20	    text-align: center;
21	    border-bottom: 1px solid #30363d;
22	}
23	.header h1 { font-size: 1.8rem; color: #f0f6fc; margin-bottom: 4px; }
24	.header .subtitle {
25	    font-size: 0.85rem; color: #8b949e; margin-top: 4px;
26	}
27	
28	/* ---- 游戏选择器 ---- */
29	.game-selector {
30	    display: flex; justify-content: center; gap: 8px;
31	    margin-top: 16px; flex-wrap: wrap;
32	}
33	.game-selector button {
34	    background: rgba(255,255,255,0.06);
35	    color: #8b949e; border: 1px solid #30363d;
36	    padding: 10px 28px; border-radius: 8px; cursor: pointer;
37	    font-size: 0.95rem; transition: all 0.25s;
38	    display: flex; align-items: center; gap: 8px;
39	}
40	.game-selector button:hover {
41	    background: rgba(255,255,255,0.10); color: #c9d1d9;
42	    border-color: #484f58;
43	}
44	.game-selector button.active {
45	    background: #1f6feb; border-color: #1f6feb; color: #fff;
46	    box-shadow: 0 0 12px rgba(31,111,235,0.3);
47	}
48	.game-selector .game-badge {
49	    font-size: 0.7rem; background: rgba(255,255,255,0.15);
50	    padding: 1px 6px; border-radius: 3px;
51	}
52	
53	/* ---- 导航栏 ---- */
54	.nav {
55	    display: flex; justify-content: center; gap: 4px;
56	    padding: 12px 24px; background: #161b22;
57	    border-bottom: 1px solid #30363d; position: sticky; top: 0; z-index: 100;
58	    flex-wrap: wrap;
59	}
60	.nav button {
61	    background: #21262d; color: #c9d1d9; border: 1px solid #30363d;
62	    padding: 7px 18px; border-radius: 6px; cursor: pointer;
63	    font-size: 0.88rem; transition: all 0.2s;
64	}
65	.nav button:hover { background: #30363d; }
66	.nav button.active { background: #1f6feb; border-color: #1f6feb; color: #fff; }
67	.nav .hero-count { color: #8b949e; font-size: 0.8rem; align-self: center; margin-left: 8px; }
68	
69	/* ---- 控制栏 ---- */
70	.controls {
71	    display: flex; justify-content: center; align-items: center; gap: 16px;
72	    padding: 12px 24px; flex-wrap: wrap;
73	}
74	.controls .label { color: #8b949e; font-size: 0.8rem; margin-right: 2px; }
75	.controls button {
76	    background: transparent; color: #8b949e; border: 1px solid #30363d;
77	    padding: 5px 14px; border-radius: 4px; cursor: pointer; font-size: 0.8rem;
78	    transition: all 0.2s;
79	}
80	.controls button:hover { border-color: #484f58; color: #c9d1d9; }
81	.controls button.active { background: #238636; border-color: #238636; color: #fff; }
82	
83	/* ---- 内容区 ---- */
84	.container { max-width: 1280px; margin: 0 auto; padding: 24px; }
85	
86	.section-header {
87	    display: flex; align-items: center; gap: 12px;
88	    margin-bottom: 20px; padding-bottom: 12px; border-bottom: 1px solid #30363d;
89	    flex-wrap: wrap;
90	}
91	.section-header h2 { font-size: 1.5rem; color: #f0f6fc; }
92	.section-header .count-badge {
93	    color: #8b949e; font-size: 0.9rem; background: #21262d;
94	    padding: 2px 10px; border-radius: 10px;
95	}
96	.section-header .hint {
97	    color: #8b949e; font-size: 0.85rem; margin-left: auto;
98	}
99	
100	/* ---- 统计卡片 ---- */
101	.stats-row { display: flex; gap: 12px; margin-bottom: 20px; flex-wrap: wrap; }
102	.stat-card {
103	    background: #161b22; border: 1px solid #30363d; border-radius: 8px;
104	    padding: 12px 16px; flex: 1; min-width: 100px; text-align: center;
105	}
106	.stat-card .stat-value { font-size: 1.4rem; font-weight: 700; color: #f0f6fc; }
107	.stat-card .stat-label { font-size: 0.75rem; color: #8b949e; margin-top: 2px; }
108	
109	/* ---- 表格 ---- */
110	.table-wrapper { overflow-x: auto; border-radius: 8px; border: 1px solid #30363d; }
111	table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
112	thead th {
113	    background: #161b22; color: #8b949e; padding: 12px 14px;
114	    text-align: left; font-weight: 600; border-bottom: 1px solid #30363d;
115	    white-space: nowrap; position: sticky; top: 0; cursor: pointer; user-select: none;
116	}
117	thead th:hover { color: #f0f6fc; }
118	thead th .sort-icon { opacity: 0.3; margin-left: 4px; }
119	thead th.sorted .sort-icon { opacity: 1; }
120	tbody td { padding: 10px 14px; border-bottom: 1px solid #21262d; }
121	tbody tr:hover { background: rgba(255,255,255,0.03); }
122	tbody tr.current-highlight { background: rgba(31,111,235,0.08); }
123	
124	/* ---- 排名数字 ---- */
125	.rank-num { font-weight: 700; font-size: 1rem; color: #f0f6fc; text-align: center; }
126	.rank-1 { color: #ffd700; font-size: 1.3rem; }
127	.rank-2 { color: #c0c0c0; font-size: 1.2rem; }
128	.rank-3 { color: #cd7f32; font-size: 1.1rem; }
129	
130	/* ---- 梯度标签 ---- */
131	.tier-badge {
132	    display: inline-block; padding: 3px 10px; border-radius: 4px;
133	    font-weight: 700; font-size: 0.8rem; color: #fff; text-align: center; min-width: 44px;
134	}
135	
136	/* ---- 分数条 ---- */
137	.score-bar-wrap { display: flex; align-items: center; gap: 8px; min-width: 120px; }
138	.score-bar { flex: 1; height: 6px; background: #21262d; border-radius: 3px; overflow: hidden; }
139	.score-bar-fill { height: 100%; border-radius: 3px; transition: width 0.3s; }
140	.score-value { font-weight: 600; font-size: 0.85rem; color: #f0f6fc; min-width: 44px; text-align: right; }
141	
142	/* ---- 英雄名 + 头像 ---- */
143	.hero-name { font-weight: 600; color: #f0f6fc; }
144	.hero-cell { display: flex; align-items: center; gap: 8px; }
145	.hero-icon {
146	    width: 32px; height: 32px; border-radius: 50%;
147	    border: 1.5px solid #30363d; object-fit: cover;
148	    background: #21262d; flex-shrink: 0;
149	}
150	
151	/* ---- 高亮色 ---- */
152	.wr-high { color: #3fb950; font-weight: 600; }
153	.wr-mid { color: #d29922; }
154	.wr-low { color: #f85149; }
155	.cw-high { color: #3fb950; font-weight: 600; }
156	.cw-mid { color: #d29922; }
157	.cw-low { color: #f85149; }
158	
159	/* ---- 搜索框 ---- */
160	.search-box {
161	    background: #21262d; border: 1px solid #30363d; border-radius: 6px;
162	    padding: 8px 14px; color: #c9d1d9; font-size: 0.9rem; width: 200px;
163	    outline: none; transition: border-color 0.2s;
164	}
165	.search-box:focus { border-color: #1f6feb; }
166	.search-box::placeholder { color: #484f58; }
167	
168	/* ---- 页脚 ---- */
169	.footer {
170	    text-align: center; padding: 24px; color: #484f58;
171	    font-size: 0.8rem; border-top: 1px solid #30363d; margin-top: 24px;
172	}
173	
174	/* ---- 梯度网格视图 ---- */
175	.tier-grid {
176	    display: flex; flex-direction: column;
177	    gap: 3px; background: #000; padding: 3px;
178	    border-radius: 8px; overflow: hidden;
179	    border: 1px solid #30363d; min-width: 320px;
180	}
181	.tier-row {
182	    display: flex; flex-direction: row; min-height: 64px;
183	    background: #161b22;
184	}
185	.tier-label {
186	    display: flex; align-items: center; justify-content: center;
187	    width: 64px; min-width: 64px; font-weight: 800; font-size: 1.1rem;
188	    color: #fff; text-shadow: 0 1px 3px rgba(0,0,0,0.5);
189	    letter-spacing: 1px; user-select: none;
190	}
191	.tier-icons {
192	    display: flex; flex-wrap: wrap; gap: 6px;
193	    padding: 8px 12px; align-items: center; flex: 1;
194	    background: #0d1117;
195	}
196	.tier-hero {
197	    display: flex; flex-direction: column; align-items: center;
198	    gap: 3px; cursor: pointer; transition: transform 0.15s, filter 0.15s;
199	    width: 64px;
200	}
201	.tier-hero:hover {
202	    transform: scale(1.12); filter: brightness(1.2);
203	}
204	.tier-hero img {
205	    width: 44px; height: 44px; border-radius: 50%;
206	    border: 2px solid #30363d; object-fit: cover;
207	    background: #21262d;
208	}
209	.tier-hero .tier-hero-name {
210	    font-size: 0.7rem; color: #8b949e; text-align: center;
211	    max-width: 60px; overflow: hidden; text-overflow: ellipsis;
212	    white-space: nowrap; line-height: 1.2;
213	}
214	.tier-hero:hover .tier-hero-name { color: #f0f6fc; }
215	
216	/* ---- 网格视图空行 ---- */
217	.tier-row-empty .tier-icons {
218	    color: #484f58; font-size: 0.8rem; font-style: italic;
219	    justify-content: flex-start; padding-left: 16px;
220	}
221	
222	/* ---- 响应式：网格视图 ---- */
223	@media (max-width: 768px) {
224	    .tier-label { width: 42px; min-width: 42px; font-size: 0.85rem; }
225	    .tier-icons { gap: 4px; padding: 6px 8px; }
226	    .tier-hero { width: 48px; }
227	    .tier-hero img { width: 34px; height: 34px; }
228	    .tier-hero .tier-hero-name { font-size: 0.62rem; max-width: 44px; }
229	    .tier-row { min-height: 48px; }
230	}
231	
232	/* ---- 无分路提示 ---- */
233	.no-lanes-notice {
234	    text-align: center; padding: 16px 24px; background: #161b22;
235	    border-bottom: 1px solid #30363d; color: #8b949e; font-size: 0.85rem;
236	}
237	
238	/* ---- 响应式 ---- */
239	@media (max-width: 768px) {
240	    .header h1 { font-size: 1.3rem; }
241	    .header { padding: 20px 16px 16px; }
242	    .game-selector button { padding: 8px 16px; font-size: 0.85rem; }
243	    .nav button { padding: 6px 12px; font-size: 0.78rem; }
244	    table { font-size: 0.75rem; }
245	    thead th { padding: 8px 10px; }
246	    tbody td { padding: 8px 10px; }
247	    .stats-row { gap: 6px; }
248	    .stat-card { padding: 8px 10px; }
249	    .stat-card .stat-value { font-size: 1.1rem; }
250	    .controls { gap: 8px; }
251	    .controls button { padding: 4px 8px; font-size: 0.7rem; }
252	    .search-box { width: 140px; font-size: 0.8rem; }
253	    .container { padding: 12px; }
254	    .score-bar-wrap { min-width: 80px; }
255	    .score-value { font-size: 0.75rem; min-width: 32px; }
256	    .section-header h2 { font-size: 1.2rem; }
257	}
