660	function sortTable(th, colIdx) {
661	  const table = th.closest("table");
662	  const tbody = table.querySelector("tbody");
663	  const rows = Array.from(tbody.querySelectorAll("tr"));
664	  const isDesc = th.classList.contains("sorted") && !th.classList.contains("desc");
665	
666	  table.querySelectorAll("th").forEach(h => { h.classList.remove("sorted", "desc"); });
667	  th.classList.add("sorted");
668	  if (isDesc) th.classList.add("desc");
669	
670	  // Determine which heroes list is active
671	  let heroes;
672	  if (gameData.hasLanes) {
673	    if (currentView === "global") {
674	      heroes = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
675	    } else {
676	      heroes = gameData.lanes[currentLane] || [];
677	    }
678	  } else {
679	    heroes = gameData.heroes;
680	  }
681	
682	  // Build column definitions
683	  let cols;
684	  if (gameData.hasLanes && currentView === "global") {
685	    cols = gameConfig.globalColumns;
686	  } else {
687	    cols = gameConfig.columns;
688	  }
689	
690	  // Handle lane-specific rank column
691	  const col = (colIdx < cols.length) ? cols[colIdx] : { field: "globalRank", type: "rank" };
692	
693	  // 动态找到英雄名列的索引（而非硬编码 cells[1]）
694	  const nameColIdx = cols.findIndex(c => c.field === "name");
695	  rows.sort((a, b) => {
696	    const heroA = heroes.find(h => h.name === a.cells[nameColIdx]?.textContent?.trim());
697	    const heroB = heroes.find(h => h.name === b.cells[nameColIdx]?.textContent?.trim());
698	    const va = heroA ? (col.field === "laneRank" ? heroA.laneRank : heroA[col.field]) : 0;
699	    const vb = heroB ? (col.field === "laneRank" ? heroB.laneRank : heroB[col.field]) : 0;
700	
701	    if (col.type === "tier") {
702	      const order = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
703	      const ia = order.indexOf(va), ib = order.indexOf(vb);
704	      return isDesc ? ib - ia : ia - ib;
705	    }
706	    const na = parseFloat(va), nb = parseFloat(vb);
707	    if (!isNaN(na) && !isNaN(nb)) {
708	      return isDesc ? nb - na : na - nb;
709	    }
710	    const sa = String(va != null ? va : ""), sb = String(vb != null ? vb : "");
711	    return isDesc ? sb.localeCompare(sa) : sa.localeCompare(sb);
712	  });
713	
714	  rows.forEach(r => tbody.appendChild(r));
715	}
